from common import *
import io
m=load(); out=io.StringIO()
def P(*a): print(*a,file=out)
P("# Paper 03 — first-pass results (public data only)\n")
P("Generated by `p03.py` 2026-11-26. Sources: County Health Rankings & Roadmaps (CHR) supplemental release (25 Mar 2026; premature death/age-adjusted premature mortality 2021-2023, life expectancy 2021-2023, PCP rate 2022 (AHRF/AMA), dentists 2023, uninsured 2023), CHR 2025 annual release (demographics, child poverty, segregation, income; measure-level data years per CHR 2025 documentation [year-by-measure PENDING]), CDC PLACES 2025 release (BRFSS 2023). Race-specific county values are as published by CHR (unreliable/suppressed values already excluded by CHR). Mississippi counties only (n=82).\n")
P("## A. Black–White gap in premature mortality (counties with both values published)\n")
rows=[]
for lab,b,w in [('Premature death, YPLL<75 per 100k (2021-23)','prem_death_black','prem_death_white'),('Premature age-adjusted mortality per 100k (2021-23)','prem_mort_black','prem_mort_white'),('Life expectancy, years (2021-23)','life_exp_black','life_exp_white')]:
    d=m[[b,w]].dropna(); diff=d[b]-d[w]
    wil=stats.wilcoxon(d[b],d[w]); 
    rows.append([lab,len(d),d[w].median(),d[b].median(),diff.median(),(diff>0).sum() if 'life' not in b else (diff<0).sum(),wil.pvalue])
t=pd.DataFrame(rows,columns=['Measure','n counties','White median','Black median','Median county difference (Black-White)','Counties where Black outcome worse','Wilcoxon p'])
P(t.to_markdown(index=False,floatfmt='.3g')); P()
P("## B. Association of overall premature mortality with primary care supply and social/economic context (OLS, HC3 robust SE; unit = county)\n")
m['pcp_per10k']=m.pcp_per100k/10; m['pov10']=m.child_poverty/10; m['black10']=m.pct_black_nh/10; m['unins']=m.uninsured_pct
P("Outcome: age-adjusted premature mortality per 100k (2021-23). PCP per 10,000 pop = PCP per 100k / 10; child poverty and %Black per 10 percentage points.\n")
for lab,xs in [('Model 1: PCP only',['pcp_per10k']),('Model 2: + child poverty',['pcp_per10k','pov10']),('Model 3: + uninsured, nonmetro, %Black (per 10 pts)',['pcp_per10k','pov10','unins','nonmetro','black10']),('Model 4: Model 3 + DRA (Delta region) county',['pcp_per10k','pov10','unins','nonmetro','black10','dra_county'])]:
    mod,t,n=ols(m,'prem_mort_agadj',xs); P(f"**{lab}** (n={n}, R2={mod.rsquared:.2f})\n"); P(t.round(3).to_markdown()); P()
P("## C. Spearman correlations (n counties)\n")
rows=[]
for y,ly in [('prem_mort_agadj','Premature age-adj mortality'),('life_exp','Life expectancy'),('pl_diabetes_pl','Diabetes prevalence (PLACES)'),('pl_chd','CHD prevalence (PLACES)'),('pl_stroke','Stroke prevalence (PLACES)'),('prev_hosp_stays','Preventable hospital stays (Medicare)')]:
    for x,lx in [('pcp_per100k','PCP per 100k'),('child_poverty','Child poverty %'),('uninsured_pct','Uninsured %'),('segregation_bw','Black/White residential segregation index'),('pct_black_nh','% Black NH')]:
        n,r,p=spearman(m[x],m[y]); rows.append([ly,lx,n,r,p])
P(pd.DataFrame(rows,columns=['Outcome','Predictor','n','rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
P("## D. Chronic-disease prevalence by Delta region (DRA) and metro status (PLACES, age-adjusted, BRFSS 2023)\n")
rows=[]
for v,l in [('pl_diabetes_pl','Diabetes'),('pl_chd','Coronary heart disease'),('pl_stroke','Stroke'),('pl_bphigh','High blood pressure'),('pl_obesity_pl','Obesity')]:
    for g,lg in [('dra_county','DRA vs non-DRA'),('nonmetro','Nonmetro vs metro')]:
        a=m[m[g]==1][v]; b=m[m[g]==0][v]; u=stats.mannwhitneyu(a,b)
        rows.append([l,lg,len(a),a.median(),len(b),b.median(),u.pvalue])
P(pd.DataFrame(rows,columns=['Condition','Comparison','n (group=1)','median group=1','n (group=0)','median group=0','Mann-Whitney p']).to_markdown(index=False,floatfmt='.3g')); P()
P("## E. Black–White gap in age-adjusted premature mortality vs county context\n")
m['gap_mort']=m.prem_mort_black-m.prem_mort_white
rows=[]
for x,lx in [('segregation_bw','Residential segregation (B/W index)'),('pcp_per100k','PCP per 100k'),('child_poverty','Child poverty %'),('pct_black_nh','% Black NH'),('median_hh_income','Median HH income')]:
    n,r,p=spearman(m[x],m['gap_mort']); rows.append([lx,n,r,p])
P(pd.DataFrame(rows,columns=['Predictor','n counties','Spearman rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
mod,t,n=ols(m,'gap_mort',['segregation_bw','pcp_per10k','pov10','nonmetro']); P(f"OLS gap ~ segregation + PCP/10k + child poverty/10pts + nonmetro (n={n}, R2={mod.rsquared:.2f})\n"); P(t.round(3).to_markdown()); P()
P("Note: ecological associations at the county level; do not imply individual-level effects. Race-specific county estimates are noisy in small counties; the gap analysis is restricted to counties with both values published (CHR).")
cols=['fips','county','population','nonmetro','dra_county','rucc2023','pct_black_nh','child_poverty','uninsured_pct','pcp_per100k','dentist_per100k','segregation_bw','premature_death_ypll','prem_death_white','prem_death_black','prem_mort_agadj','prem_mort_white','prem_mort_black','life_exp','life_exp_white','life_exp_black','pl_diabetes_pl','pl_chd','pl_stroke','pl_bphigh','pl_obesity_pl','prev_hosp_stays']
m[cols].to_csv('results/p03/p03_county_dataset.csv',index=False)
open('results/p03/p03_results.md','w').write(out.getvalue()); print(out.getvalue())
